mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def gettok():
    global tok
    while True:
        try:
            tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    if tok is None: gettok()
    for a in range(200):
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            if e.code==401: gettok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404 and "/customers/" in p: return None
            else: notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
orders={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in orders: dups+=1
        else: orders[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
statuses={}
for o in orders.values():
    statuses[o["status"]]=statuses.get(o["status"],0)+1
    if o["status"]!="shipped":continue
    s=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(s)
    if t.tzinfo is None: odd.append(("naive",o["id"],s)); t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c));continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(pages,d["total_pages"],len(orders),statuses,odd[:10],len(odd),notes[:5],len(notes))
print({c:v for c,v in cust.items() if v and (v["region"] not in reg or not isinstance(v["discount_pct"],int))})
EOF
python3 -I /tmp/work/r.py; cat /workspace/result.json

